@push('scripts')<script>const dataUrl='{{ route('dashboard.data') }}',refreshUrl='{{ route('dashboard.refresh') }}';const money=n=>Number(n||0).toLocaleString('zh-TW',{maximumFractionDigits:2});const date=s=>s?new Date(s).toLocaleDateString('zh-TW'):'-';async function load(){try{const r=await fetch(dataUrl,{cache:'no-store'});const d=await r.json();const a=d.results||[];document.getElementById('candidate').textContent=a.filter(x=>x.signal==='BUY_CANDIDATE').length;document.getElementById('buy').textContent=a.filter(x=>x.signal==='BUY_CANDIDATE').length;document.getElementById('sell').textContent=a.filter(x=>x.signal==='SELL_ALERT').length;document.getElementById('dividend').textContent='NT$'+money(Math.max(...a.map(x=>Number(x.estimated_dividend||0)),0));document.getElementById('updated').textContent='最後更新：'+new Date(d.updated_at).toLocaleString('zh-TW');document.getElementById('status').textContent='● 系統正常';document.getElementById('rows').innerHTML=a.length?a.map(x=>{const c=x.signal==='BUY_CANDIDATE'?'buy':x.signal==='SELL_ALERT'?'sell':x.signal==='HOLD'?'hold':'wait';return `<tr><td>${x.etf.code}</td><td>${x.etf.name}</td><td>${money(x.quote_price)}</td><td>${date(x.ex_dividend_date)}</td><td>${date(x.last_buy_date)}</td><td>${date(x.pay_date)}</td><td>${money(x.etf.dividends?.[0]?.dividend_amount||x.estimated_dividend/(x.shares||1))}</td><td>${money(x.shares)} (${x.lots}張)</td><td>NT$${money(x.investment_amount)}</td><td>NT$${money(x.estimated_dividend)}</td><td>${x.capital_gain===null?'-':'NT$'+money(x.capital_gain)}</td><td class="${c}">${x.signal}</td></tr>`}).join(''):'<tr><td colspan="12">目前沒有策略結果；請先執行更新。</td></tr>'}catch(e){document.getElementById('status').textContent='資料讀取失敗：'+e.message}}document.getElementById('save').onclick=async()=>{const token=document.querySelector('meta[name=csrf-token]').content;const amount=document.getElementById('account').value;document.getElementById('status').textContent='更新 TWSE 資料中…';await fetch(refreshUrl,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({account_amount:amount})});await load()};load();setInterval(load,300000);</script>@endpush
